/** Represents an ARGB (alpha, red, green, blue) color. */
export interface Color {
    /** The alpha component (0–255). */
    a: number;
    /** The red component (0–255). */
    r: number;
    /** The green component (0–255). */
    g: number;
    /** The blue component (0–255). */
    b: number;
}
